#[no_mangle]
pub extern "C" fn unreachable_quotient_i32(a: i32, b: i32) -> i32 {
    unsafe {
        if b == 0 || (a == i32::MIN && b == -1) {
            core::hint::unreachable_unchecked();
        }
    }
    a / b
}

#[no_mangle]
pub extern "C" fn two_hint_quotient_i32(a: i32, b: i32) -> i32 {
    unsafe {
        core::hint::assert_unchecked(b != 0);
        core::hint::assert_unchecked(b != -1);
    }
    a / b
}

#[no_mangle]
pub extern "C" fn widened_quotient_i32(a: i32, b: i32) -> i32 {
    unsafe {
        core::hint::assert_unchecked(b != 0);
    }
    (((a as i64) / (b as i64)) as i32)
}

#[no_mangle]
pub extern "C" fn widened_remainder_i32(a: i32, b: i32) -> i32 {
    unsafe {
        core::hint::assert_unchecked(b != 0);
    }
    (((a as i64) % (b as i64)) as i32)
}

#[no_mangle]
pub extern "C" fn widened_quotient_i8(a: i8, b: i8) -> i8 {
    unsafe {
        core::hint::assert_unchecked(b != 0);
    }
    (((a as i32) / (b as i32)) as i8)
}

#[no_mangle]
pub extern "C" fn widened_quotient_i64(a: i64, b: i64) -> i64 {
    unsafe {
        core::hint::assert_unchecked(b != 0);
    }
    (((a as i128) / (b as i128)) as i64)
}

#[no_mangle]
pub extern "C" fn both_hint_quotient_i64(a: i64, b: i64) -> i64 {
    unsafe {
        if b == 0 || (a == i64::MIN && b == -1) {
            core::hint::unreachable_unchecked();
        }
    }
    a / b
}
